import math
import sys


def dew_or_frost_point(x_gkg: float, p_pa: float) -> float:
    if x_gkg <= 0 or p_pa <= 0:
        raise ValueError("x_gkg and p_pa must be positive")

    x = x_gkg / 1000.0
    e = x * p_pa / (0.622 + x)

    # Für e == 0 ist die Gleichung nur im Limes der unteren Singularität
    # lösbar; da unter Wasser die Lösung unter 0 °C liegt, wird frostweise
    # die untere Eis-Singularität zurückgegeben.
    if e <= 0:
        return -272.62

    log_e = math.log(e)
    log_611 = math.log(611.2)

    base = 1.00062 + 3.14e-8 * p_pa
    coeff = 5.6e-7
    log_coeff = math.log(coeff)

    # Schwelle, ab der coeff*t*t in Gleitkomma-Addition leicht überläuft.
    safe_t = math.sqrt(sys.float_info.max / coeff)

    def log_f(t: float) -> float:
        """log(1.00062 + 3.14e-8*p + 5.6e-7*t**2), numerisch robust."""
        if not math.isfinite(t):
            if base == math.inf:
                return math.inf
            if t == 0:
                return math.log(base)
            # Für t -> ±inf dominiert coeff*t^2; log_f -> inf.
            return math.inf

        if abs(t) > safe_t:
            log_ct2 = log_coeff + 2.0 * math.log(abs(t))
            if base <= 0:
                return log_ct2
            log_base = math.log(base)
            m = max(log_base, log_ct2)
            return m + math.log1p(math.exp(min(log_base, log_ct2) - m))

        val = base + coeff * t * t
        if val <= 0:
            # Nur zur numerischen Sicherheit; mathematisch ist val > 0.
            if t == 0:
                return math.log(base)
            return math.log(coeff) + 2.0 * math.log(abs(t))
        return math.log(val)

    def log_f_prime(t: float) -> float:
        """Ableitung von log_f."""
        if not math.isfinite(t):
            return 0.0

        if abs(t) > safe_t:
            # d/dt log(coeff*t^2) = 2/t
            return 2.0 / t

        val = base + coeff * t * t
        if val <= 0:
            return 0.0
        return (2.0 * coeff * t) / val

    def solve_saturation(a: float, b: float) -> float:
        """
        Löse h(t)=log(f(t)) + log(611.2) + a*t/(b+t) - log(e) = 0.
        Monoton wachsend für t > -b.
        """
        log_base = log_f(0.0)
        h0 = log_base + log_611 - log_e

        # Startnäherung: ohne starke Druck-/Temperatur-Enhancement,
        # oder asymptotisch für sehr große Dampfdruckwerte.
        L = log_e - log_611 - log_base
        if L < a:
            if a - L == 0:
                t_start = 0.0
            else:
                t_start = b * L / (a - L)
        else:
            # Für sehr große e wächst log_f(t) ~ log(coeff)+2 log(t).
            # Saturationssättigung asymptotisch: log_611 + a.
            exponent = (log_e - log_611 - a - log_coeff) / 2.0
            try:
                t_start = math.exp(exponent)
            except OverflowError:
                t_start = sys.float_info.max

        if not math.isfinite(t_start):
            t_start = sys.float_info.max if t_start > 0 else 0.0

        low = math.nextafter(-b, math.inf)

        # Oberes Intervall: bei h(0) < 0 liegt die Wurzel über 0 °C.
        if h0 < 0:
            upper = max(1.0, t_start if t_start > 0 else 1.0)
            if not math.isfinite(upper):
                upper = sys.float_info.max

            def h_upper(u: float) -> float:
                den = b + u
                if den <= 0:
                    den = math.nextafter(0.0, math.inf)
                return log_f(u) + log_611 + a * u / den - log_e

            h_u = h_upper(upper)
            while h_u < 0:
                upper *= 2.0
                if not math.isfinite(upper):
                    return upper
                h_u = h_upper(upper)
        else:
            upper = 0.0

        if upper <= low:
            upper = math.nextafter(low, math.inf)

        def h(t: float) -> float:
            den = b + t
            if den <= 0:
                den = math.nextafter(0.0, math.inf)
            return log_f(t) + log_611 + a * t / den - log_e

        def h_prime(t: float) -> float:
            den = b + t
            if den <= 0:
                den = math.nextafter(0.0, math.inf)
            return log_f_prime(t) + a / (den * den)

        # Startpunkt: gute Näherung oder Mittelpunkt.
        t = t_start
        if t <= low or t >= upper:
            t = (low + upper) / 2.0

        # Newton-Verfahren mit Bruchintervall-Absicherung.
        for _ in range(120):
            h_t = h(t)

            if h_t == 0:
                return t

            if h_t > 0:
                upper = t
            else:
                low = t

            if upper - low <= 1e-12:
                return (low + upper) / 2.0

            hp = h_prime(t)
            if not math.isfinite(hp) or hp <= 0:
                t_next = (low + upper) / 2.0
            else:
                t_next = t - h_t / hp

            if not math.isfinite(t_next) or t_next <= low or t_next >= upper:
                t_next = (low + upper) / 2.0

            if abs(t_next - t) < 1e-12:
                return t_next

            t = t_next

        # Falls Newton nicht vollständig konvergiert: letztes Intervall halbieren.
        for _ in range(60):
            t_mid = (low + upper) / 2.0
            h_mid = h(t_mid)

            if h_mid == 0:
                return t_mid
            if h_mid > 0:
                upper = t_mid
            else:
                low = t_mid

            if upper - low <= 1e-12:
                return (low + upper) / 2.0

        return (low + upper) / 2.0

    t_water = solve_saturation(17.62, 243.12)

    if t_water < 0:
        return solve_saturation(22.46, 272.62)

    return t_water

import math
import re

_NUMBER_RE = re.compile(r"(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?")

_CONSTANTS = {
    "pi": math.pi,
    "e": math.e,
}

_FUNCTIONS = {
    "sin",
    "cos",
    "sqrt",
    "exp",
    "ln",
}


def _tokenize(s: str):
    tokens = []
    i = 0
    n = len(s)

    while i < n:
        c = s[i]

        if c.isspace():
            i += 1
            continue

        if c in "+-*/^()":
            tokens.append(("op", c))
            i += 1
            continue

        m = _NUMBER_RE.match(s, i)
        if m is not None:
            text = m.group(0)
            try:
                value = float(text)
            except ValueError:
                raise ValueError("invalid number") from None

            tokens.append(("number", value))
            i = m.end()
            continue

        if c.isalpha() or c == "_":
            j = i + 1
            while j < n and (s[j].isalnum() or s[j] == "_"):
                j += 1

            tokens.append(("name", s[i:j]))
            i = j
            continue

        raise ValueError("invalid token")

    return tokens


def _safe_power(base: float, exponent: float) -> float:
    if base == 0.0 and exponent < 0.0:
        raise ValueError("division by zero")

    try:
        return math.pow(base, exponent)
    except ValueError:
        raise ValueError("undefined power") from None
    except OverflowError:
        return math.inf


def _call_function(name: str, arg: float) -> float:
    try:
        if name == "sqrt":
            if arg < 0.0:
                raise ValueError("sqrt domain error")
            return math.sqrt(arg)

        if name == "ln":
            if arg <= 0.0:
                raise ValueError("ln domain error")
            return math.log(arg)

        if name == "exp":
            try:
                return math.exp(arg)
            except OverflowError:
                return math.inf

        if name == "sin":
            return math.sin(arg)

        if name == "cos":
            return math.cos(arg)

        raise ValueError("unknown function")
    except ValueError:
        raise ValueError("function domain error") from None


class _Parser:
    def __init__(self, tokens, variables):
        self.tokens = tokens
        self.pos = 0
        self.variables = variables

    def _peek(self):
        if self.pos >= len(self.tokens):
            return None
        return self.tokens[self.pos]

    def _consume(self, op: str):
        tok = self._peek()
        if tok is None or tok[0] != "op" or tok[1] != op:
            raise ValueError(f"expected '{op}'")
        self.pos += 1

    def _parse_expression(self) -> float:
        value = self._parse_term()

        while True:
            tok = self._peek()
            if tok is None or tok[0] != "op" or tok[1] not in ("+", "-"):
                break

            op = tok[1]
            self.pos += 1

            rhs = self._parse_term()
            if op == "+":
                value += rhs
            else:
                value -= rhs

        return value

    def _parse_term(self) -> float:
        value = self._parse_unary()

        while True:
            tok = self._peek()
            if tok is None or tok[0] != "op" or tok[1] not in ("*", "/"):
                break

            op = tok[1]
            self.pos += 1

            rhs = self._parse_unary()

            if op == "*":
                value *= rhs
            else:
                if rhs == 0.0:
                    raise ValueError("division by zero")
                value /= rhs

        return value

    def _parse_unary(self) -> float:
        tok = self._peek()

        if tok is not None and tok[0] == "op":
            if tok[1] == "+":
                self.pos += 1
                return self._parse_unary()

            if tok[1] == "-":
                self.pos += 1
                return -self._parse_unary()

        return self._parse_power()

    def _parse_power(self) -> float:
        value = self._parse_primary()

        while True:
            tok = self._peek()
            if tok is None or tok[0] != "op" or tok[1] != "^":
                break

            self.pos += 1
            exponent = self._parse_unary()
            value = _safe_power(value, exponent)

        return value

    def _parse_primary(self) -> float:
        tok = self._peek()
        if tok is None:
            raise ValueError("unexpected end of expression")

        if tok[0] == "number":
            self.pos += 1
            return float(tok[1])

        if tok[0] == "op" and tok[1] == "(":
            self.pos += 1
            value = self._parse_expression()
            self._consume(")")
            return value

        if tok[0] == "name":
            self.pos += 1
            name = tok[1]

            nxt = self._peek()
            if (
                nxt is not None
                and nxt[0] == "op"
                and nxt[1] == "("
                and name in _FUNCTIONS
            ):
                self.pos += 1
                arg = self._parse_expression()
                self._consume(")")
                return _call_function(name, arg)

            if self.variables is not None and name in self.variables:
                raw = self.variables[name]
                try:
                    return float(raw)
                except (TypeError, ValueError):
                    raise ValueError("invalid variable") from None

            if name in _CONSTANTS:
                return _CONSTANTS[name]

            raise ValueError("unknown name")

        raise ValueError("unexpected token")

    def parse(self) -> float:
        value = self._parse_expression()
        if self.pos != len(self.tokens):
            raise ValueError("unexpected token")
        return float(value)


def evaluate_expr(s: str, variables: dict | None = None) -> float:
    tokens = _tokenize(s)
    parser = _Parser(tokens, variables)
    return parser.parse()

def rx_fullmatch(pattern: str, text: str) -> bool:
    states = []

    def new_eps_state():
        states.append(["eps", []])
        return len(states) - 1

    def new_char_state(pred, nxt):
        states.append(["char", pred, nxt])
        return len(states) - 1

    def add_eps(u, v):
        states[u][1].append(v)

    class Fragment:
        __slots__ = ("start", "end")

        def __init__(self, start, end):
            self.start = start
            self.end = end

    def literal_pred(target):
        def pred(ch):
            return ch == target
        return pred

    dot_pred = lambda ch: True

    def class_pred(ranges, literals, negated):
        def pred(ch):
            ok = False
            for a, b in ranges:
                if a <= ch <= b:
                    ok = True
                    break
            if not ok:
                for c in literals:
                    if ch == c:
                        ok = True
                        break
            if negated:
                return not ok
            return ok
        return pred

    def empty_frag():
        s = new_eps_state()
        return Fragment(s, s)

    def concat_frags(frags):
        if not frags:
            return empty_frag()
        if len(frags) == 1:
            return frags[0]
        start = frags[0].start
        end = frags[-1].end
        for i in range(len(frags) - 1):
            add_eps(frags[i].end, frags[i + 1].start)
        return Fragment(start, end)

    def union_fr(frags):
        start = new_eps_state()
        out = new_eps_state()
        for frag in frags:
            add_eps(start, frag.start)
            add_eps(frag.end, out)
        return Fragment(start, out)

    def star_frag(frag):
        start = new_eps_state()
        out = new_eps_state()
        add_eps(start, frag.start)
        add_eps(start, out)
        add_eps(frag.end, start)
        add_eps(frag.end, out)
        return Fragment(start, out)

    def plus_frag(frag):
        start = new_eps_state()
        out = new_eps_state()
        add_eps(start, frag.start)
        add_eps(frag.end, start)
        add_eps(frag.end, out)
        return Fragment(start, out)

    def question_frag(frag):
        start = new_eps_state()
        out = new_eps_state()
        add_eps(start, out)
        add_eps(start, frag.start)
        add_eps(frag.end, out)
        return Fragment(start, out)

    def char_frag(pred):
        s = new_char_state(pred, new_eps_state())
        return Fragment(s, len(states) - 1)

    class Parser:
        def __init__(self, pat):
            self.p = pat
            self.n = len(pat)
            self.pos = 0

        def parse(self):
            frag = self.parse_alternation(("|", ")"))
            if self.pos != self.n:
                raise ValueError("unexpected closing parenthesis")
            return frag

        def parse_alternation(self, stop_chars):
            alternatives = [self.parse_sequence(stop_chars)]
            while self.pos < self.n and self.p[self.pos] == "|":
                self.pos += 1
                alternatives.append(self.parse_sequence(stop_chars))
            if len(alternatives) == 1:
                return alternatives[0]
            return union_fr(alternatives)

        def parse_sequence(self, stop_chars):
            frags = []
            while self.pos < self.n and self.p[self.pos] not in stop_chars:
                frag = self.parse_atom()
                if self.pos < self.n and self.p[self.pos] in ("*", "+", "?"):
                    q = self.p[self.pos]
                    self.pos += 1
                    if q == "*":
                        frag = star_frag(frag)
                    elif q == "+":
                        frag = plus_frag(frag)
                    else:
                        frag = question_frag(frag)
                frags.append(frag)
            return concat_frags(frags)

        def parse_atom(self):
            if self.pos >= self.n:
                return empty_frag()
            ch = self.p[self.pos]
            if ch in ("*", "+", "?"):
                raise ValueError("quantor without operand")

            if ch == "(":
                self.pos += 1
                frag = self.parse_alternation(("|", ")"))
                if self.pos >= self.n or self.p[self.pos] != ")":
                    raise ValueError("unclosed parenthesis")
                self.pos += 1
                return frag

            if ch == "[":
                pred = self.parse_class()
                return char_frag(pred)

            if ch == "\\":
                self.pos += 1
                if self.pos >= self.n:
                    raise ValueError("unterminated escape")
                lit = self.p[self.pos]
                self.pos += 1
                return char_frag(literal_pred(lit))

            if ch == ".":
                self.pos += 1
                return char_frag(dot_pred)

            self.pos += 1
            return char_frag(literal_pred(ch))

        def parse_class(self):
            self.pos += 1
            negated = False
            if self.pos < self.n and self.p[self.pos] == "^":
                negated = True
                self.pos += 1

            tokens = []
            while self.pos < self.n and self.p[self.pos] != "]":
                if self.p[self.pos] == "\\":
                    self.pos += 1
                    if self.pos >= self.n:
                        raise ValueError("unterminated class")
                    tokens.append((self.p[self.pos], True))
                    self.pos += 1
                else:
                    tokens.append((self.p[self.pos], False))
                    self.pos += 1

            if self.pos >= self.n:
                raise ValueError("unterminated class")
            self.pos += 1

            ranges = []
            literals = []
            i = 0
            while i < len(tokens):
                if i + 2 < len(tokens) and tokens[i + 1][0] == "-" and not tokens[i + 1][1]:
                    a = tokens[i][0]
                    b = tokens[i + 2][0]
                    if a > b:
                        raise ValueError("invalid character class range")
                    ranges.append((a, b))
                    i += 3
                else:
                    literals.append(tokens[i][0])
                    i += 1

            return class_pred(ranges, literals, negated)

    parser = Parser(pattern)
    frag = parser.parse()

    active = [frag.start]
    seen = set()
    stack = active[:]
    active = []
    while stack:
        s = stack.pop()
        if s in seen:
            continue
        seen.add(s)
        active.append(s)
        if states[s][0] == "eps":
            stack.extend(states[s][1])

    final = frag.end
    for ch in text:
        nxt = []
        for s in active:
            kind = states[s][0]
            if kind == "char" and states[s][1](ch):
                nxt.append(states[s][2])

        seen = set()
        stack = nxt[:]
        active = []
        while stack:
            s = stack.pop()
            if s in seen:
                continue
            seen.add(s)
            active.append(s)
            if states[s][0] == "eps":
                stack.extend(states[s][1])

    return final in active

import heapq

def k_shortest_paths(graph: dict, src, dst, k: int) -> list[tuple[float, list]]:
    if k <= 0:
        return []
    if src == dst:
        return [(0.0, [src])]

    def _dijkstra(start, target, removed_nodes: set, removed_edges: set):
        if start == target:
            return (0.0, [start])

        dist = {start: 0.0}
        prev = {}
        heap = [(0.0, start)]

        while heap:
            cost, node = heapq.heappop(heap)
            if cost != dist.get(node, float("inf")):
                continue

            if node == target:
                path = []
                cur = target
                while cur != start:
                    path.append(cur)
                    nxt = prev.get(cur)
                    if nxt is None:
                        return None
                    cur = nxt
                path.append(start)
                path.reverse()
                return (cost, path)

            for nxt, weight in graph.get(node, {}).items():
                if nxt in removed_nodes:
                    continue
                if (node, nxt) in removed_edges:
                    continue

                new_cost = cost + float(weight)
                if new_cost < dist.get(nxt, float("inf")):
                    dist[nxt] = new_cost
                    prev[nxt] = node
                    heapq.heappush(heap, (new_cost, nxt))

        return None

    def _path_cost(path):
        cost = 0.0
        for u, v in zip(path[:-1], path[1:]):
            weight = graph.get(u, {}).get(v)
            if weight is None:
                return None
            cost += float(weight)
        return cost

    shortest = _dijkstra(src, dst, set(), set())
    if shortest is None:
        return []

    paths = [(float(shortest[0]), shortest[1])]
    found = {tuple(shortest[1])}
    candidates = []
    seen_candidates = set()
    counter = 0

    for _ in range(1, k):
        last_path = paths[-1][1]

        for root_idx in range(len(last_path) - 1):
            spur_node = last_path[root_idx]
            root_path = last_path[:root_idx + 1]
            root_tuple = tuple(root_path)

            removed_edges = set()
            for _, path in paths:
                if len(path) > root_idx + 1 and tuple(path[:root_idx + 1]) == root_tuple:
                    removed_edges.add((path[root_idx], path[root_idx + 1]))

            removed_nodes = set(root_path[:-1])

            spur = _dijkstra(spur_node, dst, removed_nodes, removed_edges)
            if spur is None:
                continue

            candidate_path = root_path[:-1] + spur[1]
            if not candidate_path or candidate_path[0] != src or candidate_path[-1] != dst:
                continue

            candidate_cost = _path_cost(candidate_path)
            if candidate_cost is None:
                continue

            candidate_tuple = tuple(candidate_path)
            if candidate_tuple in found or candidate_tuple in seen_candidates:
                continue

            seen_candidates.add(candidate_tuple)
            counter += 1
            heapq.heappush(candidates, (float(candidate_cost), counter, candidate_tuple))

        popped = False
        while candidates:
            cost, _, next_tuple = heapq.heappop(candidates)
            if next_tuple in found:
                continue

            found.add(next_tuple)
            paths.append((float(cost), list(next_tuple)))
            popped = True
            break

        if not popped:
            break

    paths.sort(key=lambda item: item[0])
    return paths

def crc_generic(data: bytes, width: int, poly: int, init: int, refin: bool, refout: bool, xorout: int) -> int:
    """
    Berechnet eine CRC nach dem Rocksoft/Williams-Parametermodell.

    Unterstützte Bitbreiten: 1..64.
    """
    if width < 1 or width > 64:
        raise ValueError("width must be in 1..64")

    mask = (1 << width) - 1
    top_mask = 1 << (width - 1)
    poly = poly & mask
    init = init & mask
    xorout = xorout & mask

    crc = init

    if refin:
        crc = _bit_reverse(crc, width)
        poly = _bit_reverse(poly, width)

    if refin:
        bit_iter = range(8)
    else:
        bit_iter = range(7, -1, -1)

    for byte in data:
        for bit_index in bit_iter:
            bit = (byte >> bit_index) & 1

            if refin:
                # Verarbeitete Bitfolge ist LSB-first und die CRC ist in
                # reflektierter Orientation. Die Polynomdivision läuft mit
                # dem reflektierten Polynom über Rechtsshifts.
                crc >>= 1
                if (crc ^ bit) & 1:
                    crc = (crc ^ poly) & mask
                else:
                    crc &= mask
            else:
                # Verarbeitete Bitfolge ist MSB-first und die CRC läuft
                # in normaler Orientation mit Linksshifts.
                if crc & top_mask:
                    crc = (crc << 1) ^ poly
                else:
                    crc <<= 1

                crc ^= bit
                crc &= mask

    if refout:
        crc = _bit_reverse(crc, width)

    crc = crc ^ xorout
    return crc & mask


def _bit_reverse(value: int, width: int) -> int:
    result = 0
    for i in range(width):
        if value & (1 << i):
            result |= 1 << (width - 1 - i)
    return result

